-- 0681: the request received and offer emails link straight to the licence upload while the renter's licence is missing
-- (docs/changes/2026-11-07-r32-booking-flows.md, item 4).
--
-- Every booking email reads app.ntf_booking (0023); it now also carries licence_missing: true while the booking's
-- renter has not sent all of the licence (front, back and the selfie when Program settings ask for it), the same check
-- as the offer's acceptance (app.licence_gate, 0130: not for an owner's booking, a rental staff added, or with the
-- switch off). renter_request_received, renter_offer_ready and renter_offer_reminder show "Upload your driver's
-- licence" with the link to /account/bookings/<n>/verify when it is true. The existing rule stays: the licence from the
-- request on, the proof of coverage after approval (only the licence is asked here).
-- No applied migration is edited.

alter function app.ntf_booking(uuid) rename to ntf_booking_pre0681;
create function app.ntf_booking(p_booking uuid) returns jsonb
language plpgsql stable security definer set search_path = public, app as $$
declare
  b bookings;
  v_driver uuid;
  v_missing boolean := false;
begin
  select * into b from bookings where id = p_booking;
  if b.id is not null and b.booking_type <> 'owner' and not coalesce(b.added_by_staff, false)
     and coalesce((app.settings()).booking_licence_required, true) and b.status in ('requested', 'offered', 'pending_payment') then
    select bd.driver_id into v_driver from booking_drivers bd where bd.booking_id = b.id and bd.role = 'renter' limit 1;
    v_missing := v_driver is not null and jsonb_array_length(coalesce(app.licence_status(b.id, v_driver) -> 'missing', '[]'::jsonb)) > 0;
  end if;
  return coalesce(app.ntf_booking_pre0681(p_booking), '{}'::jsonb) || jsonb_build_object('licence_missing', v_missing);
end $$;
do $$
declare g text;
begin
  execute 'revoke all on function app.ntf_booking(uuid) from public, anon, authenticated';
  foreach g in array array['anon', 'authenticated', 'service_role'] loop
    if has_function_privilege(g, 'app.ntf_booking_pre0681(uuid)', 'execute') then execute format('grant execute on function app.ntf_booking(uuid) to %I', g); end if;
  end loop;
end $$;

